package com.codex.quartermaster;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CodexQuartermasterPluginRunner
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CodexQuartermasterPlugin.class);
		RuneLite.main(args);
	}
}

package com.codex.quartermaster;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(CodexQuartermasterConfig.GROUP)
public interface CodexQuartermasterConfig extends Config
{
	String GROUP = "codexquartermaster";

	/** Where the plaque shows. */
	enum PlaqueMode
	{
		AT_THE_BANK,
		ALWAYS,
		NEVER
	}

	@ConfigItem(
		keyName = "warnTrips",
		name = "Warn at trips left",
		description = "When you set out with this many trips of supplies or fewer left, say so in the chat box",
		position = 0
	)
	@Range(min = 0, max = 50)
	default int warnTrips()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "plaque",
		name = "Supply plaque",
		description = "Show a small plaque in the game view with how many trips your bank supports and what runs out first",
		position = 1
	)
	default PlaqueMode plaque()
	{
		return PlaqueMode.AT_THE_BANK;
	}

	@ConfigItem(
		keyName = "measured",
		name = "Plan from your trips",
		description = "Once a kit has been measured over a couple of trips, plan with what you really used instead of the kit's own amounts",
		position = 2
	)
	default boolean measured()
	{
		return true;
	}

	@ConfigItem(
		keyName = "recognise",
		name = "Recognise packed kits",
		description = "When you close the bank carrying one of your saved kits, choose it automatically",
		position = 3
	)
	default boolean recognise()
	{
		return true;
	}
}

package com.codex.quartermaster;

import com.codex.quartermaster.core.Kit;
import com.codex.quartermaster.core.Plan;
import com.codex.quartermaster.core.Prices;
import com.codex.quartermaster.core.Quarters;
import com.codex.quartermaster.core.Trip;
import com.codex.quartermaster.core.Usage;
import com.codex.quartermaster.overlay.SupplyPlaque;
import com.codex.quartermaster.ui.Actions;
import com.codex.quartermaster.ui.Format;
import com.codex.quartermaster.ui.ItemIcons;
import com.codex.quartermaster.ui.QuartermasterPanel;
import com.codex.quartermaster.ui.Sigil;
import com.codex.quartermaster.ui.Theme;
import com.codex.quartermaster.ui.View;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.AsyncBufferedImage;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Codex Quartermaster",
	description = "Pick the content you are doing and see how many trips your bank supports, what runs out first and what restocking costs at Grand Exchange prices",
	tags = {"supplies", "bank", "trips", "restock", "potions", "food", "boss", "grand exchange", "codex"}
)
public class CodexQuartermasterPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(CodexQuartermasterPlugin.class);
	private static final String QUARTERS_KEY = "quarters";
	/** Ticks between saves while something has changed. */
	private static final int SAVE_TICKS = 50;
	/** Ticks between recounts at today's prices, about a minute. */
	private static final int REPRICE_TICKS = 100;
	private static final int[] POUCH_RUNES = {
		VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6
	};
	private static final int[] POUCH_AMOUNTS = {
		VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3,
		VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6
	};
	private static final int[] POUCHES = {
		ItemID.BH_RUNE_POUCH, ItemID.BH_RUNE_POUCH_TROUVER, ItemID.DIVINE_RUNE_POUCH, ItemID.DIVINE_RUNE_POUCH_TROUVER
	};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private Gson gson;

	@Inject
	private CodexQuartermasterConfig config;

	private final SupplyPlaque plaque = new SupplyPlaque();
	private final Map<Integer, String> names = new HashMap<>();
	private final Prices prices = id -> itemManager.getItemPrice(id);

	private QuartermasterPanel panel;
	private NavigationButton navButton;

	private String profile;
	private Quarters quarters;
	/** What was carried when last seen, so the panel still counts it while logged out. */
	private Map<Integer, Long> carried = Collections.emptyMap();
	private boolean bankOpen;
	private boolean dirty;
	private boolean unsaved;
	private int ticks;

	@Provides
	CodexQuartermasterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CodexQuartermasterConfig.class);
	}

	@Override
	protected void startUp()
	{
		ItemIcons icons = (itemId, onLoaded) ->
		{
			AsyncBufferedImage image = itemManager.getImage(itemId);
			image.onLoaded(onLoaded);
			return image;
		};
		panel = new QuartermasterPanel(icons, new PanelActions());
		navButton = NavigationButton.builder()
			.tooltip("Codex Quartermaster")
			.icon(Sigil.icon(16))
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(plaque);
		clientThread.invokeLater(() ->
		{
			loadProfile();
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				carried = readCarried();
				ItemContainer bank = client.getItemContainer(InventoryID.BANK);
				if (bank != null && quarters != null)
				{
					quarters.observeBank(contents(bank), System.currentTimeMillis());
					unsaved = true;
				}
			}
			publish();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(plaque);
		clientToolbar.removeNavigation(navButton);
		clientThread.invokeLater(() ->
		{
			save();
			quarters = null;
			profile = null;
			names.clear();
			bankOpen = false;
		});
		panel = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			bankOpen = false;
			save();
			publish();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		save();
		loadProfile();
		bankOpen = false;
		carried = client.getGameState() == GameState.LOGGED_IN ? readCarried() : Collections.emptyMap();
		publish();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CodexQuartermasterConfig.GROUP.equals(event.getGroup()))
		{
			dirty = true;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (client.getGameState() != GameState.LOGGED_IN || quarters == null)
		{
			return;
		}
		int id = event.getContainerId();
		if (id == InventoryID.BANK)
		{
			quarters.observeBank(contents(event.getItemContainer()), System.currentTimeMillis());
			unsaved = true;
			dirty = true;
		}
		else if (id == InventoryID.INV || id == InventoryID.WORN)
		{
			carried = readCarried();
			dirty = true;
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() != InterfaceID.BANKMAIN || quarters == null)
		{
			return;
		}
		bankOpen = true;
		// The bank has just opened, so what is carried is still what came back from the trip.
		Trip trip = quarters.endTrip(readCarried(), System.currentTimeMillis(), prices);
		if (trip != null)
		{
			unsaved = true;
		}
		dirty = true;
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() != InterfaceID.BANKMAIN || !event.isUnload() || quarters == null)
		{
			return;
		}
		bankOpen = false;
		carried = readCarried();
		if (config.recognise() && quarters.recognise(carried) != null)
		{
			unsaved = true;
		}
		quarters.startTrip(carried, System.currentTimeMillis());
		warn();
		dirty = true;
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (quarters != null && event.getActor() == client.getLocalPlayer())
		{
			// What is lost on death is not what the trip used.
			quarters.voidTrip();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (quarters == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		ticks++;
		if (unsaved && ticks % SAVE_TICKS == 0)
		{
			save();
		}
		if (dirty || ticks % REPRICE_TICKS == 0)
		{
			publish();
		}
	}

	/** When setting out with the chosen kit packed and few trips left, says what runs out and what restocking costs. */
	private void warn()
	{
		Kit kit = quarters.activeKit();
		if (!quarters.hasBank() || Quarters.packed(kit, carried) < 0.5)
		{
			return;
		}
		Plan plan = quarters.plan(kit, carried, prices, config.measured());
		Plan.Line first = plan.limiting();
		int trips = plan.trips();
		if (first == null || trips > config.warnTrips())
		{
			return;
		}
		String supply = supplyName(first).toLowerCase(Locale.ENGLISH);
		// What is carried counts, so one trip left is the one setting out now.
		String text;
		if (trips == 0)
		{
			text = "not enough " + supply + " for a full " + kit.getName() + " trip.";
		}
		else if (trips == 1)
		{
			text = "this is your last " + kit.getName() + " trip before " + supply + " runs out.";
		}
		else
		{
			text = trips + " " + kit.getName() + " trips left, counting this one; " + supply + " runs out first.";
		}
		ChatMessageBuilder line = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT).append("Codex Quartermaster: ")
			.append(ChatColorType.NORMAL).append(text);
		if (plan.restockCost() > 0)
		{
			line.append(" Restocking to " + plan.getTarget() + " trips costs " + Format.coins(plan.restockCost()) + ".");
		}
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(line.build())
			.build());
	}

	private Map<Integer, Long> contents(ItemContainer container)
	{
		Map<Integer, Long> items = new HashMap<>();
		if (container == null)
		{
			return items;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() < 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			items.merge(itemManager.canonicalize(item.getId()), (long) item.getQuantity(), Long::sum);
		}
		return items;
	}

	/** The inventory, worn gear and the runes in a carried rune pouch. */
	private Map<Integer, Long> readCarried()
	{
		Map<Integer, Long> items = contents(client.getItemContainer(InventoryID.INV));
		contents(client.getItemContainer(InventoryID.WORN)).forEach((id, q) -> items.merge(id, q, Long::sum));
		boolean pouch = false;
		for (int id : POUCHES)
		{
			pouch |= items.containsKey(id);
		}
		if (pouch)
		{
			EnumComposition runes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
			for (int i = 0; i < POUCH_RUNES.length; i++)
			{
				int type = client.getVarbitValue(POUCH_RUNES[i]);
				int amount = client.getVarbitValue(POUCH_AMOUNTS[i]);
				int itemId = type > 0 ? runes.getIntValue(type) : -1;
				if (itemId > 0 && amount > 0)
				{
					items.merge(itemId, (long) amount, Long::sum);
				}
			}
		}
		return items;
	}

	/**
	 * Whether a carried item is a supply a saved kit should count. Stackables are, worn gear and
	 * other equipment are not, and anything else is when it can be bought again.
	 */
	private boolean isSupply(int itemId)
	{
		ItemComposition item = itemManager.getItemComposition(itemId);
		if (item.isStackable())
		{
			return true;
		}
		ItemStats stats = itemManager.getItemStats(itemId);
		if (stats != null && stats.isEquipable())
		{
			return false;
		}
		return item.isTradeable();
	}

	private void loadProfile()
	{
		profile = configManager.getRSProfileKey();
		quarters = null;
		if (profile == null)
		{
			return;
		}
		try
		{
			String saved = configManager.getRSProfileConfiguration(CodexQuartermasterConfig.GROUP, QUARTERS_KEY);
			if (saved != null && !saved.isEmpty())
			{
				Quarters read = gson.fromJson(saved, Quarters.class);
				quarters = read == null ? null : read.repair();
			}
		}
		catch (JsonParseException e)
		{
			log.warn("Could not read the saved quarters, starting afresh", e);
		}
		if (quarters == null)
		{
			quarters = new Quarters();
		}
		unsaved = false;
		dirty = true;
	}

	private void save()
	{
		if (profile == null || quarters == null || !unsaved)
		{
			return;
		}
		unsaved = false;
		configManager.setConfiguration(CodexQuartermasterConfig.GROUP, profile, QUARTERS_KEY, gson.toJson(quarters));
	}

	/** Works out every kit's plan and hands the panel and the plaque what they show. */
	private void publish()
	{
		dirty = false;
		QuartermasterPanel target = panel;
		long now = System.currentTimeMillis();
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		if (quarters == null)
		{
			plaque.show(null, null, null);
			if (target != null)
			{
				SwingUtilities.invokeLater(() -> target.update(View.loggedOut()));
			}
			return;
		}
		boolean measured = config.measured();
		Kit active = quarters.activeKit();
		List<Plan> plans = new ArrayList<>();
		Plan chosen = null;
		for (Kit kit : quarters.allKits())
		{
			Plan plan = quarters.plan(kit, carried, prices, measured);
			plans.add(plan);
			if (kit == active)
			{
				chosen = plan;
			}
			for (Plan.Line line : plan.getLines())
			{
				name(line.getSupply().getIcon());
				line.getHeld().keySet().forEach(this::name);
				line.getBuys().forEach(b -> name(b.getItemId()));
			}
		}
		Usage usage = quarters.usage(active.getId());
		List<Trip> trips = usage == null ? Collections.emptyList() : new ArrayList<>(usage.getRecent());
		Player player = client.getLocalPlayer();
		View.State state = !quarters.hasBank() ? View.State.WAITING_FOR_BANK : View.State.READY;
		View view = new View(state, loggedIn && player != null ? player.getName() : null, chosen, plans, trips,
			usage == null ? 0 : usage.getTrips(), quarters.getBankSeen(), bankOpen, new HashMap<>(names), config.warnTrips(), now);

		CodexQuartermasterConfig.PlaqueMode mode = config.plaque();
		boolean showPlaque = loggedIn && quarters.hasBank() && chosen != null
			&& (mode == CodexQuartermasterConfig.PlaqueMode.ALWAYS || mode == CodexQuartermasterConfig.PlaqueMode.AT_THE_BANK && bankOpen);
		if (showPlaque)
		{
			int n = chosen.trips();
			Plan.Line first = chosen.limiting();
			String figure = n == Plan.UNLIMITED ? "Ample" : n + (n == 1 ? " trip" : " trips");
			String note = active.getName() + (first == null ? "" : "  -  " + supplyName(first) + " first");
			plaque.show(figure, note, n == Plan.UNLIMITED ? Theme.GOLD : Theme.trips(n, config.warnTrips()));
		}
		else
		{
			plaque.show(null, null, null);
		}
		if (target != null)
		{
			SwingUtilities.invokeLater(() -> target.update(view));
		}
	}

	private String supplyName(Plan.Line line)
	{
		return line.getSupply().getName() != null ? line.getSupply().getName() : name(line.getSupply().getIcon());
	}

	private String name(int itemId)
	{
		return names.computeIfAbsent(itemId, id -> itemManager.getItemComposition(id).getName());
	}

	/** The panel's buttons; each change is made on the client thread, where the quarters live. */
	private final class PanelActions implements Actions
	{
		@Override
		public void choose(String kitId)
		{
			clientThread.invokeLater(() ->
			{
				if (quarters != null)
				{
					quarters.select(kitId);
					unsaved = true;
					publish();
				}
			});
		}

		@Override
		public void target(int trips)
		{
			clientThread.invokeLater(() ->
			{
				if (quarters != null)
				{
					quarters.setTarget(trips);
					unsaved = true;
					publish();
				}
			});
		}

		@Override
		public void capture()
		{
			Quarters q = quarters;
			if (q == null || client.getGameState() != GameState.LOGGED_IN)
			{
				return;
			}
			String suggested = "My kit " + (q.getSavedKits().size() + 1);
			Object answer = JOptionPane.showInputDialog(panel, "Name this kit, such as the boss it is for:", "Save a kit",
				JOptionPane.PLAIN_MESSAGE, null, null, suggested);
			if (answer == null || answer.toString().trim().isEmpty())
			{
				return;
			}
			String name = answer.toString().trim();
			clientThread.invokeLater(() ->
			{
				if (quarters == null)
				{
					return;
				}
				carried = readCarried();
				Kit kit = quarters.capture(name.length() > 32 ? name.substring(0, 32) : name, carried, CodexQuartermasterPlugin.this::isSupply);
				if (kit == null)
				{
					chatMessageManager.queue(QueuedMessage.builder()
						.type(ChatMessageType.CONSOLE)
						.runeLiteFormattedMessage(new ChatMessageBuilder()
							.append(ChatColorType.HIGHLIGHT).append("Codex Quartermaster: ")
							.append(ChatColorType.NORMAL).append("nothing you are carrying is a supply. Withdraw your food, potions and the like, then save the kit.")
							.build())
						.build());
					return;
				}
				unsaved = true;
				save();
				publish();
			});
		}

		@Override
		public void forget(String kitId)
		{
			int ok = JOptionPane.showConfirmDialog(panel, "Forget this kit and the trips measured with it?", "Forget kit",
				JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
			if (ok != JOptionPane.OK_OPTION)
			{
				return;
			}
			clientThread.invokeLater(() ->
			{
				if (quarters != null && quarters.forget(kitId))
				{
					unsaved = true;
					save();
					publish();
				}
			});
		}
	}
}

package com.codex.quartermaster.core;

import java.util.ArrayList;
import java.util.List;

/**
 * What a trip to one piece of content takes. Presets ship with the plugin and start from typical
 * numbers; kits the player saves are taken from what they actually carried.
 */
public class Kit
{
	private String id;
	private String name;
	private List<Need> needs = new ArrayList<>();
	private transient boolean preset;

	public Kit()
	{
	}

	public Kit(String id, String name, List<Need> needs, boolean preset)
	{
		this.id = id;
		this.name = name;
		this.needs = new ArrayList<>(needs);
		this.preset = preset;
	}

	public String getId()
	{
		return id;
	}

	public String getName()
	{
		return name;
	}

	public List<Need> getNeeds()
	{
		return needs;
	}

	public boolean isPreset()
	{
		return preset;
	}

	public Need need(String supply)
	{
		for (Need n : needs)
		{
			if (n.getSupply().equals(supply))
			{
				return n;
			}
		}
		return null;
	}

	/** Drops a supply from a saved kit, for things that were carried but are not supplies. */
	public boolean remove(String supply)
	{
		return needs.removeIf(n -> n.getSupply().equals(supply));
	}

	/** Restores what saved data can leave out. */
	Kit repair()
	{
		if (needs == null)
		{
			needs = new ArrayList<>();
		}
		needs.removeIf(n -> n == null || n.getSupply() == null || Supplies.get(n.getSupply()) == null);
		return this;
	}
}

package com.codex.quartermaster.core;

/** One supply a kit takes, and how much of it a trip is planned to use. */
public class Need
{
	private String supply;
	private int perTrip;

	public Need()
	{
	}

	public Need(String supply, int perTrip)
	{
		this.supply = supply;
		this.perTrip = perTrip;
	}

	public String getSupply()
	{
		return supply;
	}

	public int getPerTrip()
	{
		return perTrip;
	}
}

package com.codex.quartermaster.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * How far a bank stretches for one kit: each supply with how many trips it lasts, the one that
 * runs out first, what a trip costs, and the shopping list to reach a number of trips.
 */
public final class Plan
{
	/** A supply that is brought along and comes back, so it never runs out. */
	public static final int UNLIMITED = Integer.MAX_VALUE;

	private final Kit kit;
	private final List<Line> lines;
	private final int target;

	Plan(Kit kit, List<Line> lines, int target)
	{
		this.kit = kit;
		this.lines = Collections.unmodifiableList(lines);
		this.target = target;
	}

	public Kit getKit()
	{
		return kit;
	}

	public List<Line> getLines()
	{
		return lines;
	}

	public int getTarget()
	{
		return target;
	}

	/** The line for one supply, or null when the kit does not take it. */
	public Line line(String supply)
	{
		for (Line l : lines)
		{
			if (l.getSupply().getKey().equals(supply))
			{
				return l;
			}
		}
		return null;
	}

	/** @return trips the bank supports, or {@link #UNLIMITED} when nothing in the kit is used up */
	public int trips()
	{
		Line first = limiting();
		return first == null ? UNLIMITED : first.getTrips();
	}

	/** The supply that runs out first, or null when nothing is used up. */
	public Line limiting()
	{
		Line first = null;
		for (Line l : lines)
		{
			if (!l.isKept() && (first == null || l.getTrips() < first.getTrips()))
			{
				first = l;
			}
		}
		return first;
	}

	/** What one trip uses, at today's cheapest prices. */
	public long tripCost()
	{
		long sum = 0;
		for (Line l : lines)
		{
			sum += l.getTripCost();
		}
		return sum;
	}

	/** What restocking to the target costs. */
	public long restockCost()
	{
		long sum = 0;
		for (Line l : lines)
		{
			sum += l.getBuyCost();
		}
		return sum;
	}

	/** Every purchase on the shopping list, biggest bill first. */
	public List<Buy> shopping()
	{
		List<Buy> all = new ArrayList<>();
		for (Line l : lines)
		{
			all.addAll(l.getBuys());
		}
		all.sort((a, b) -> Long.compare(b.getCost(), a.getCost()));
		return all;
	}

	/** Supplies short of the target that the Grand Exchange cannot sell. */
	public List<Line> unbuyable()
	{
		List<Line> out = new ArrayList<>();
		for (Line l : lines)
		{
			if (l.getShort() > 0 && l.getBuys().isEmpty())
			{
				out.add(l);
			}
		}
		return out;
	}

	/** One supply of the kit against the bank. */
	public static final class Line
	{
		private final Supply supply;
		private final long have;
		private final double perTrip;
		private final boolean measured;
		private final int trips;
		private final long shortfall;
		private final List<Buy> buys;
		private final long tripCost;
		private final Map<Integer, Long> held;

		Line(Supply supply, long have, double perTrip, boolean measured, int trips, long shortfall, List<Buy> buys, long tripCost, Map<Integer, Long> held)
		{
			this.supply = supply;
			this.have = have;
			this.perTrip = perTrip;
			this.measured = measured;
			this.trips = trips;
			this.shortfall = shortfall;
			this.buys = Collections.unmodifiableList(buys);
			this.tripCost = tripCost;
			this.held = Collections.unmodifiableMap(held);
		}

		public Supply getSupply()
		{
			return supply;
		}

		/** Units held across the bank and what is carried. */
		public long getHave()
		{
			return have;
		}

		/** Units a trip uses, as planned or as measured. */
		public double getPerTrip()
		{
			return perTrip;
		}

		public boolean isMeasured()
		{
			return measured;
		}

		public int getTrips()
		{
			return trips;
		}

		/** Brought along and never used up. */
		public boolean isKept()
		{
			return trips == UNLIMITED;
		}

		/** Units missing to reach the target. */
		public long getShort()
		{
			return shortfall;
		}

		public List<Buy> getBuys()
		{
			return buys;
		}

		public long getBuyCost()
		{
			long sum = 0;
			for (Buy b : buys)
			{
				sum += b.getCost();
			}
			return sum;
		}

		public long getTripCost()
		{
			return tripCost;
		}

		/** How many of each item that counts toward this supply are held, most first. */
		public Map<Integer, Long> getHeld()
		{
			return held;
		}
	}

	/** One line of the shopping list. */
	public static final class Buy
	{
		private final int itemId;
		private final long quantity;
		private final long price;

		Buy(int itemId, long quantity, long price)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.price = price;
		}

		public int getItemId()
		{
			return itemId;
		}

		public long getQuantity()
		{
			return quantity;
		}

		public long getPrice()
		{
			return price;
		}

		public long getCost()
		{
			return quantity * price;
		}
	}
}

package com.codex.quartermaster.core;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Works out a {@link Plan}: how many trips the items held support, and what to buy for more. */
public final class Planner
{
	private Planner()
	{
	}

	/**
	 * @param held every item in the bank and carried, by id
	 * @param usage what this kit has been measured using, or null
	 * @param measured plan from the measured amounts once they are trusted
	 * @param target trips to restock to
	 */
	public static Plan plan(Kit kit, Usage usage, Map<Integer, Long> held, Prices prices, int target, boolean measured)
	{
		boolean useMeasured = measured && usage != null && usage.isTrusted();
		List<Plan.Line> lines = new ArrayList<>();
		for (Need need : kit.getNeeds())
		{
			Supply supply = Supplies.get(need.getSupply());
			if (supply == null)
			{
				continue;
			}
			double perTrip = need.getPerTrip();
			boolean fromTrips = false;
			if (useMeasured && usage.perTrip(supply.getKey()) >= 0)
			{
				perTrip = usage.perTrip(supply.getKey());
				fromTrips = true;
			}
			long have = supply.count(held);
			// Measured amounts are averages; a fraction of a unit a trip is noise, not a supply.
			boolean kept = perTrip < 0.5;
			int trips = kept ? Plan.UNLIMITED : (int) Math.min(Integer.MAX_VALUE - 1, (long) Math.floor(have / perTrip));

			long shortfall = kept ? 0 : Math.max(0, (long) Math.ceil(target * perTrip - have));
			int cheapest = cheapest(supply, prices);
			double unitPrice = cheapest < 0 ? 0 : prices.price(cheapest) / (double) supply.getUnits().get(cheapest);
			List<Plan.Buy> buys = new ArrayList<>();
			if (shortfall > 0 && cheapest >= 0)
			{
				int per = supply.getUnits().get(cheapest);
				long quantity = (shortfall + per - 1) / per;
				buys.add(new Plan.Buy(cheapest, quantity, prices.price(cheapest)));
			}
			long tripCost = kept || cheapest < 0 ? 0 : Math.round(perTrip * unitPrice);
			lines.add(new Plan.Line(supply, have, kept ? 0 : perTrip, fromTrips, trips, shortfall, buys, tripCost, heldOf(supply, held)));
		}
		return new Plan(kit, lines, target);
	}

	/** @return the item that buys this supply most cheaply per unit, or -1 when none has a price */
	static int cheapest(Supply supply, Prices prices)
	{
		int best = -1;
		double bestEach = 0;
		for (Map.Entry<Integer, Integer> e : supply.getUnits().entrySet())
		{
			long price = prices.price(e.getKey());
			if (price <= 0)
			{
				continue;
			}
			double each = price / (double) e.getValue();
			if (best < 0 || each < bestEach)
			{
				best = e.getKey();
				bestEach = each;
			}
		}
		return best;
	}

	/** What units of a supply cost at the cheapest item that buys them, or 0 without a price. */
	static long cost(Supply supply, long units, Prices prices)
	{
		int best = cheapest(supply, prices);
		return best < 0 ? 0 : Math.round(units * prices.price(best) / (double) supply.getUnits().get(best));
	}

	private static Map<Integer, Long> heldOf(Supply supply, Map<Integer, Long> held)
	{
		List<Map.Entry<Integer, Long>> found = new ArrayList<>();
		for (int id : supply.getUnits().keySet())
		{
			Long q = held.get(id);
			if (q != null && q > 0)
			{
				found.add(Map.entry(id, q));
			}
		}
		found.sort((a, b) -> Long.compare(b.getValue() * supply.getUnits().get(b.getKey()), a.getValue() * supply.getUnits().get(a.getKey())));
		Map<Integer, Long> out = new LinkedHashMap<>();
		for (Map.Entry<Integer, Long> e : found)
		{
			out.put(e.getKey(), e.getValue());
		}
		return out;
	}
}

