			ItemID.DRAGON_BOLTS_ENCHANTED_RUBY, 1,
			ItemID.DRAGON_BOLTS_ENCHANTED_DIAMOND, 1);
	}

	private Supplies()
	{
	}

	private static void group(String key, String name, String unit, int icon, int... pairs)
	{
		Map<Integer, Integer> units = new LinkedHashMap<>();
		for (int i = 0; i + 1 < pairs.length; i += 2)
		{
			units.put(pairs[i], pairs[i + 1]);
			HOME.putIfAbsent(pairs[i], key);
		}
		GROUPS.put(key, new Supply(key, name, unit, icon, units));
	}

	/** The supply for a key: a pooled group, or a single item for "item:" keys. Null when unknown. */
	public static Supply get(String key)
	{
		Supply group = GROUPS.get(key);
		if (group != null)
		{
			return group;
		}
		if (key != null && key.startsWith("item:"))
		{
			try
			{
				return Supply.item(Integer.parseInt(key.substring(5)));
			}
			catch (NumberFormatException e)
			{
				return null;
			}
		}
		return null;
	}

	/** The key an item is filed under when a kit is captured from what is carried. */
	public static String keyFor(int itemId)
	{
		String group = HOME.get(itemId);
		return group != null ? group : Supply.itemKey(itemId);
	}

	public static boolean pooled(int itemId)
	{
		return HOME.containsKey(itemId);
	}

	public static Collection<Supply> groups()
	{
		return Collections.unmodifiableCollection(GROUPS.values());
	}
}

package com.codex.quartermaster.core;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * One thing a trip uses up, counted in its own unit: food in hitpoints healed, potions in doses,
 * bolts one by one. A supply can be met by several items, so four doses of prayer potion and four
 * of super restore count the same, and a shark and a manta ray both count as food.
 */
public final class Supply
{
	private static final String ITEM = "item:";

	private final String key;
	private final String name;
	private final String unit;
	private final int icon;
	private final Map<Integer, Integer> units;

	Supply(String key, String name, String unit, int icon, Map<Integer, Integer> units)
	{
		this.key = key;
		this.name = name;
		this.unit = unit;
		this.icon = icon;
		this.units = Collections.unmodifiableMap(new LinkedHashMap<>(units));
	}

	/** A supply that is one item and nothing else, such as a teleport tablet or a rune. */
	public static Supply item(int itemId)
	{
		return new Supply(itemKey(itemId), null, null, itemId, Collections.singletonMap(itemId, 1));
	}

	public static String itemKey(int itemId)
	{
		return ITEM + itemId;
	}

	public String getKey()
	{
		return key;
	}

	/** @return the supply's name, or null for a single item, which is named after the item */
	public String getName()
	{
		return name;
	}

	/** @return "hp", "doses" and the like, or null when it is counted in items */
	public String getUnit()
	{
		return unit;
	}

	public int getIcon()
	{
		return icon;
	}

	public boolean isItem()
	{
		return key.startsWith(ITEM);
	}

	/** Every item that counts, with how many units one of it is worth. */
	public Map<Integer, Integer> getUnits()
	{
		return units;
	}

	/** How much of this supply a set of items holds, in units. */
	public long count(Map<Integer, Long> items)
	{
		long total = 0;
		for (Map.Entry<Integer, Integer> e : units.entrySet())
		{
			Long qty = items.get(e.getKey());
			if (qty != null && qty > 0)
			{
				total += qty * e.getValue();
			}
		}
		return total;
	}
}

package com.codex.quartermaster.core;

import java.util.LinkedHashMap;
import java.util.Map;

/** One measured trip: when it ran, what each supply it took was used down by, and what that cost. */
public class Trip
{
	private long start;
	private long end;
	private Map<String, Long> used = new LinkedHashMap<>();
	private long cost;

	public Trip()
	{
	}

	Trip(long start, long end, Map<String, Long> used, long cost)
	{
		this.start = start;
		this.end = end;
		this.used = new LinkedHashMap<>(used);
		this.cost = cost;
	}

	public long getStart()
	{
		return start;
	}

	public long getEnd()
	{
		return end;
	}

	public Map<String, Long> getUsed()
	{
		return used;
	}

	public long getCost()
	{
		return cost;
	}

	public long duration()
	{
		return Math.max(0, end - start);
	}
}

package com.codex.quartermaster.core;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * What one kit really uses, learned from the trips the player has made with it. The first trips
 * are averaged plainly; after that each new trip moves the average by an eighth, so a change of
 * gear or method shows within a few trips without one bad trip swinging the plan.
 */
public class Usage
{
	/** Trips before the measured amounts are trusted over the kit's own. */
	public static final int TRUSTED = 2;
	private static final int WINDOW = 8;
	private static final int RECENT = 30;

	private int trips;
	private Map<String, Double> perTrip = new LinkedHashMap<>();
	private List<Trip> recent = new ArrayList<>();

	public int getTrips()
	{
		return trips;
	}

	public boolean isTrusted()
	{
		return trips >= TRUSTED;
	}

	/** @return the average used a trip, or a negative number when this supply was never measured */
	public double perTrip(String supply)
	{
		Double v = perTrip.get(supply);
		return v == null ? -1 : v;
	}

	/** Measured trips, newest last. */
	public List<Trip> getRecent()
	{
		return recent;
	}

	public Trip last()
	{
		return recent.isEmpty() ? null : recent.get(recent.size() - 1);
	}

	/** The average supply cost of the measured trips at the prices of their day, or -1 with none. */
	public long averageCost()
	{
		if (recent.isEmpty())
		{
			return -1;
		}
		long sum = 0;
		for (Trip t : recent)
		{
			sum += t.getCost();
		}
		return sum / recent.size();
	}

	void record(Kit kit, Trip trip)
	{
		trips++;
		int n = Math.min(trips, WINDOW);
		for (Need need : kit.getNeeds())
		{
			String key = need.getSupply();
			long used = trip.getUsed().getOrDefault(key, 0L);
			Double avg = perTrip.get(key);
			// A supply added to the kit after it was first measured starts from its first trip.
			perTrip.put(key, avg == null ? used : avg + (used - avg) / n);
		}
		recent.add(trip);
		while (recent.size() > RECENT)
		{
			recent.remove(0);
		}
	}

	Usage repair()
	{
		if (perTrip == null)
		{
			perTrip = new LinkedHashMap<>();
		}
		if (recent == null)
		{
			recent = new ArrayList<>();
		}
		recent.removeIf(t -> t == null || t.getUsed() == null);
		return this;
	}
}

package com.codex.quartermaster.overlay;

import com.codex.quartermaster.ui.Sigil;
import com.codex.quartermaster.ui.Theme;
