package com.codex.quartermaster.ui;

import com.codex.quartermaster.core.Plan;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** A kit at a glance: its name, how many trips the bank supports, and what runs out first. Click to choose it. */
class KitCard extends Card
{
	KitCard(Plan plan, View view, boolean chosen, Runnable choose, Runnable forget)
	{
		super(new BorderLayout(0, 6));
		setBorder(new EmptyBorder(7, 12, 7, 10));
		int trips = plan.trips();
		Color color = trips == Plan.UNLIMITED ? Theme.TEXT_MUTED : Theme.trips(trips, view.warn);
		accent(chosen ? Theme.GOLD : Theme.alpha(color, 160));
		highlighted(chosen);
		Plan.Line first = plan.limiting();
		String note;
		if (first == null)
		{
			note = "nothing is used up";
		}
		else if (trips == 0)
		{
			note = "out of " + view.name(first).toLowerCase();
		}
		else
		{
			note = view.name(first) + " first";
		}
		add(new Face(plan.getKit().getName(), (plan.getKit().isPreset() ? "Preset" : "Your kit") + "  -  " + note,
			trips == Plan.UNLIMITED ? "-" : Format.trips(trips), color, chosen), BorderLayout.CENTER);
		// Chosen by clicking anywhere but the forget button, which is added after so it keeps its own clicks.
		onClick(choose);
		if (forget != null)
		{
			JPanel row = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
			row.setOpaque(false);
			row.add(new CodexButton("Forget this kit", false, forget));
			add(row, BorderLayout.SOUTH);
		}
	}

	private static final class Face extends JComponent
	{
		private final String name;
		private final String note;
		private final String trips;
		private final Color color;
		private final boolean chosen;

		Face(String name, String note, String trips, Color color, boolean chosen)
		{
			this.name = name;
			this.note = note;
			this.trips = trips;
			this.color = color;
			this.chosen = chosen;
			setPreferredSize(new Dimension(10, 30));
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			Theme.smooth(g);
			int w = getWidth();
			g.setFont(Theme.title());
			FontMetrics bold = g.getFontMetrics();
			g.setFont(Theme.small());
			int tw = Math.max(bold.stringWidth(trips), g.getFontMetrics().stringWidth("trips"));
			g.setFont(Theme.title());
			Ui.shadowed(g, trips, w - bold.stringWidth(trips), bold.getAscent() + 1, color);
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			FontMetrics small = g.getFontMetrics();
			g.drawString("trips", w - small.stringWidth("trips"), 28);
			g.setFont(Theme.body());
			FontMetrics fm = g.getFontMetrics();
			Ui.shadowed(g, Ui.clip(name, fm, w - tw - 10), 0, fm.getAscent() + 1, chosen ? Theme.GOLD_BRIGHT : Theme.TEXT);
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip(note, small, w - tw - 10), 0, 28);
			g.dispose();
		}
	}
}

package com.codex.quartermaster.ui;

import com.codex.quartermaster.core.Plan;
import com.codex.quartermaster.core.Supplies;
import com.codex.quartermaster.core.Supply;
import com.codex.quartermaster.core.Trip;
import com.codex.quartermaster.core.Usage;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics;
import java.awt.GridLayout;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

/**
 * The Quartermaster side panel: the crest, then three pages. Supplies is the chosen kit against
 * the bank, Restock is the shopping list to reach a number of trips, and Kits is every kit at a
 * glance, where a new one is saved from what is carried.
 */
public class QuartermasterPanel extends PluginPanel
{
	static final int WIDTH = 200;
	private static final String[] TABS = {"supplies", "restock", "kits"};
	private static final int[] TARGETS = {5, 10, 25, 50, 100};
	private static final int RECENT = 5;
	private static final Map<String, String> SHORT = new HashMap<>();

	static
	{
		SHORT.put("FOOD", "hp");
		SHORT.put("BREW", "brew");
		SHORT.put("PRAYER", "prayer");
		SHORT.put("RANGING", "ranging");
		SHORT.put("MAGIC", "magic");
		SHORT.put("COMBAT", "combat");
		SHORT.put("SUPER_ANTIFIRE", "antifire");
		SHORT.put("ANTIFIRE", "antifire");
		SHORT.put("ANTIVENOM", "anti-venom");
		SHORT.put("STAMINA", "stamina");
		SHORT.put("DRAGON_BOLTS", "bolts");
	}

	private final ItemIcons icons;
	private final Actions actions;
	private final Crest crest = new Crest();
	private final Segmented tabs = new Segmented(true, "Supplies", "Restock", "Kits");
	private final Segmented target = new Segmented(false, "5", "10", "25", "50", "100");
	private final CardLayout cards = new CardLayout();
	private final JPanel content = new JPanel(cards);
	private final JScrollPane supplies = scroller();
	private final JScrollPane restock = scroller();
	private final JScrollPane kits = scroller();

	private View view = View.loggedOut();

	public QuartermasterPanel(ItemIcons icons, Actions actions)
	{
		super(false);
		this.icons = icons;
		this.actions = actions;
		setLayout(new BorderLayout());
		setBackground(Theme.INK);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		north.add(crest, BorderLayout.NORTH);
		JPanel tabHolder = new JPanel(new BorderLayout());
		tabHolder.setOpaque(false);
		tabHolder.setBorder(new EmptyBorder(8, 8, 2, 8));
		tabHolder.add(tabs, BorderLayout.CENTER);
		north.add(tabHolder, BorderLayout.SOUTH);
		add(north, BorderLayout.NORTH);

		content.setOpaque(false);
		content.add(supplies, TABS[0]);
		content.add(restock, TABS[1]);
		content.add(kits, TABS[2]);
		add(content, BorderLayout.CENTER);

		tabs.onChange(this::showTab);
		target.setSelected(1, false);
		target.onChange(i -> actions.target(TARGETS[i]));
		rebuild();
	}

	private static JScrollPane scroller()
	{
		JScrollPane scroll = new JScrollPane();
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		return scroll;
	}

	/** Called on the Swing thread whenever anything shown changes. */
	public void update(View view)
	{
		this.view = view;
		if (view.active != null)
		{
			for (int i = 0; i < TARGETS.length; i++)
			{
				if (TARGETS[i] == view.active.getTarget())
				{
					target.setSelected(i, false);
				}
			}
		}
		updateCrest();
		rebuild();
	}

	/** Opens one tab, for previews and tests. */
	public void showTab(int index)
	{
		tabs.setSelected(index, false);
		cards.show(content, TABS[index]);
	}

	private void updateCrest()
	{
		Plan plan = view.active;
		if (plan == null)
		{
			crest.update("SUPPLIES", null, false, "Log in to count your supplies", null, Theme.TEXT_MUTED, Theme.GOLD);
			return;
		}
		String heading = plan.getKit().getName().toUpperCase(Locale.ENGLISH);
		if (view.state == View.State.WAITING_FOR_BANK)
		{
			crest.update(heading, null, false, "Open your bank to begin", null, Theme.mix(Theme.TEXT_MUTED, Theme.GOLD, 0.3), Theme.GOLD);
			return;
		}
		int trips = plan.trips();
		Plan.Line first = plan.limiting();
		if (first == null)
		{
			crest.update(heading, trips, true, "Nothing in this kit is used up", "Nothing is used up", Theme.TEXT_MUTED, Theme.GOLD);
			return;
		}
		Color color = Theme.trips(trips, view.warn);
		String supply = view.name(first);
		String status = trips == 0 ? "Out of " + supply.toLowerCase(Locale.ENGLISH) : supply + " runs out first";
		String shortStatus = trips == 0 ? "Out of " + supply.toLowerCase(Locale.ENGLISH) : supply + " first";
		crest.update(heading, trips, false, status, shortStatus, trips <= view.warn ? color : Theme.mix(Theme.TEXT_MUTED, Theme.GOLD, 0.35), trips <= view.warn ? color : Theme.GOLD);
	}

	private void rebuild()
	{
		rebuildSupplies();
		rebuildRestock();
		rebuildKits();
	}

	private boolean waiting(StackPanel stack)
	{
		if (view.active == null)
		{
			stack.add(note("The stores are closed", "Log in and Codex Quartermaster counts how many trips your bank supports for the content you choose, what runs out first, and what restocking costs at Grand Exchange prices."));
			return true;
		}
		if (view.state == View.State.WAITING_FOR_BANK)
		{
			stack.add(note("Open your bank once", "The Quartermaster counts from your bank. After the first look it remembers the bank as last seen, so the panel works anywhere."));
			return true;
		}
		return false;
	}

	// The Supplies tab.

	private void rebuildSupplies()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (waiting(stack))
		{
			replace(supplies, stack);
			return;
		}
		Plan plan = view.active;
		JPanel tiles = new JPanel(new GridLayout(1, 2, 6, 0));
		tiles.setOpaque(false);
		tiles.add(new StatTile(Format.coins(plan.tripCost()), "Per trip", "at today's prices", Theme.GOLD));
		boolean measured = view.measured >= Usage.TRUSTED;
		tiles.add(new StatTile(measured ? String.valueOf(view.measured) : "-", "Measured",
			measured ? "trips learned" : view.measured == 1 ? "1 trip so far" : "make a trip", measured ? Theme.TEAL : Theme.TEXT_MUTED));
		stack.add(tiles);

		stack.add(new SectionHeader("Supplies", plan.getKit().getName()));
		Card list = new Card(new BorderLayout());
		StackPanel rows = new StackPanel(2, 0);
		List<Plan.Line> lines = new ArrayList<>(plan.getLines());
		lines.sort((a, b) -> Integer.compare(a.getTrips(), b.getTrips()));
		Plan.Line first = plan.limiting();
		for (Plan.Line line : lines)
		{
			rows.add(new SupplyRow(line, view, plan.getTarget(), line == first, icons));
		}
		list.add(rows, BorderLayout.CENTER);
		stack.add(list);
		String foot = measured
			? "* measured from your trips with this kit"
			: plan.getKit().isPreset() ? "Typical amounts until your own trips are measured" : "As packed until your own trips are measured";
		stack.add(Ui.wrapped(foot, Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));

		if (!view.trips.isEmpty())
		{
			long sum = 0;
			for (Trip t : view.trips)
			{
				sum += t.getCost();
			}
			stack.add(new SectionHeader("Recent trips", "avg " + Format.coins(sum / view.trips.size())));
			Card recent = new Card(new BorderLayout());
			StackPanel tripRows = new StackPanel(4, 0);
			for (int i = view.trips.size() - 1; i >= 0 && i >= view.trips.size() - RECENT; i--)
			{
				Trip t = view.trips.get(i);
				tripRows.add(new TripRow(t, used(t)));
			}
			recent.add(tripRows, BorderLayout.CENTER);
			stack.add(recent);
		}
		if (!view.bankOpen && view.bankSeen > 0)
		{
			stack.add(Ui.label("Bank as last seen " + Format.ago(view.now - view.bankSeen), Theme.small(), Theme.TEXT_FAINT));
		}
		replace(supplies, stack);
	}

	private String used(Trip trip)
	{
		StringBuilder text = new StringBuilder();
		List<Map.Entry<String, Long>> entries = new ArrayList<>(trip.getUsed().entrySet());
		// Pooled supplies first, they say the most in the least room.
		entries.sort((a, b) -> Boolean.compare(!SHORT.containsKey(a.getKey()), !SHORT.containsKey(b.getKey())));
		for (Map.Entry<String, Long> e : entries)
		{
			if (e.getValue() <= 0)
			{
				continue;
			}
			if (text.length() > 0)
			{
				text.append(", ");
			}
			String label = SHORT.get(e.getKey());
			if (label == null)
			{
				Supply s = Supplies.get(e.getKey());
				label = s == null ? "" : view.name(s.getIcon());
			}
			text.append(Format.amount(e.getValue())).append(' ').append(label);
		}
		return text.length() == 0 ? "nothing used" : text.toString();
	}

	// The Restock tab.

	private void rebuildRestock()
	{
		StackPanel stack = new StackPanel(8, 8);
		stack.add(new SectionHeader("Restock to", "trips"));
		stack.add(target);
		if (waiting(stack))
		{
			replace(restock, stack);
			return;
		}
		Plan plan = view.active;
		List<Plan.Buy> shopping = plan.shopping();
		List<Plan.Line> unbuyable = plan.unbuyable();
		int trips = plan.trips();

		JPanel tiles = new JPanel(new GridLayout(1, 2, 6, 0));
		tiles.setOpaque(false);
		tiles.add(new StatTile(shopping.isEmpty() ? "Nothing" : Format.coins(plan.restockCost()), "Restock", shopping.isEmpty() ? "already stocked" : shopping.size() + (shopping.size() == 1 ? " item" : " items"), Theme.GOLD));
		tiles.add(new StatTile(trips == Plan.UNLIMITED ? "-" : Format.trips(trips) + " to " + Math.max(trips, plan.getTarget()),
			"Trips", unbuyable.isEmpty() ? "after buying" : "some not sold", Theme.trips(Math.min(trips, plan.getTarget()), view.warn)));
		stack.add(tiles);

		if (shopping.isEmpty() && unbuyable.isEmpty())
		{
			stack.add(note("Stocked for " + plan.getTarget() + " trips", "Your bank already holds enough for " + plan.getTarget() + " trips of " + plan.getKit().getName() + ". Pick a higher target to plan a bigger restock."));
			replace(restock, stack);
			return;
		}
		if (!shopping.isEmpty())
		{
			stack.add(new SectionHeader("Shopping list", Format.coins(plan.restockCost())));
			Card list = new Card(new BorderLayout());
			StackPanel rows = new StackPanel(2, 0);
			for (Plan.Buy buy : shopping)
			{
				rows.add(new BuyRow(buy.getItemId(), view.name(buy.getItemId()),
					"Buy " + String.format(Locale.ENGLISH, "%,d", buy.getQuantity()) + " at " + Format.coins(buy.getPrice()),
					Format.coins(buy.getCost()), Theme.GOLD, icons));
			}
			list.add(rows, BorderLayout.CENTER);
			stack.add(list);
			JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
			buttons.setOpaque(false);
			buttons.add(new CodexButton("Copy shopping list", false, () -> copy(plan)));
			stack.add(buttons);
		}
		if (!unbuyable.isEmpty())
		{
			stack.add(new SectionHeader("Not on the exchange"));
			Card list = new Card(new BorderLayout());
			list.accent(Theme.EMBER);
			StackPanel rows = new StackPanel(2, 0);
			for (Plan.Line line : unbuyable)
			{
				rows.add(new BuyRow(line.getSupply().getIcon(), view.name(line),
					"Make or gather " + Format.amount(line.getShort()) + View.unit(line) + " more", "-", Theme.EMBER, icons));
			}
			list.add(rows, BorderLayout.CENTER);
			stack.add(list);
		}
		stack.add(Ui.wrapped("Each supply is bought as whichever item is cheapest per dose or hitpoint, at the client's Grand Exchange prices.", Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
		replace(restock, stack);
	}

	private void copy(Plan plan)
	{
		StringBuilder text = new StringBuilder(plan.getKit().getName()).append(" restock for ").append(plan.getTarget()).append(" trips\n");
		for (Plan.Buy buy : plan.shopping())
		{
			text.append(view.name(buy.getItemId())).append(" x ").append(buy.getQuantity()).append('\n');
		}
		text.append("Total ").append(Format.coins(plan.restockCost())).append(" gp");
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text.toString()), null);
	}

	// The Kits tab.

	private void rebuildKits()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (view.active == null)
		{
			waiting(stack);
			replace(kits, stack);
			return;
		}
		Card save = new Card(new BorderLayout(0, 6));
		save.accent(Theme.TEAL);
		save.add(Ui.label("Pack it, then save it", Theme.body(), Theme.GOLD), BorderLayout.NORTH);
		save.add(Ui.wrapped("Withdraw what you take on a trip and save it as a kit. The Quartermaster then recognises it whenever you pack it, and learns what you really use.",
			Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		buttons.setOpaque(false);
		buttons.add(new CodexButton("Save my inventory as a kit", true, actions::capture));
		save.add(buttons, BorderLayout.SOUTH);
		stack.add(save);

		boolean anySaved = false;
		for (Plan plan : view.plans)
		{
			if (!plan.getKit().isPreset())
			{
				if (!anySaved)
				{
					stack.add(new SectionHeader("Your kits"));
					anySaved = true;
				}
				String id = plan.getKit().getId();
				boolean chosen = id.equals(view.active.getKit().getId());
				stack.add(new KitCard(plan, view, chosen, () -> actions.choose(id), chosen ? () -> actions.forget(id) : null));
			}
		}
		stack.add(new SectionHeader("Presets"));
		for (Plan plan : view.plans)
		{
			if (plan.getKit().isPreset())
			{
				String id = plan.getKit().getId();
				stack.add(new KitCard(plan, view, id.equals(view.active.getKit().getId()), () -> actions.choose(id), null));
			}
		}
		replace(kits, stack);
	}

	static Card note(String title, String text)
	{
		Card card = new Card(new BorderLayout(0, 4));
		card.accent(Theme.GOLD_DIM);
		card.add(Ui.label(title, Theme.body(), Theme.GOLD), BorderLayout.NORTH);
		card.add(Ui.wrapped(text, Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		return card;
	}

	private static void replace(JScrollPane scroll, JComponent view)
	{
		int position = scroll.getVerticalScrollBar().getValue();
		scroll.setViewportView(view);
		scroll.revalidate();
		SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(position));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		g.setColor(Theme.INK);
		g.fillRect(0, 0, getWidth(), getHeight());
	}
}

package com.codex.quartermaster.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A small-caps heading with a gold diamond and a line that fades into the dark. */
public class SectionHeader extends JComponent
{
	private final String text;
	private final String trailing;

	public SectionHeader(String text)
	{
		this(text, null);
	}

	public SectionHeader(String text, String trailing)
	{
		this.text = text.toUpperCase();
		this.trailing = trailing;
		setFont(Theme.small());
		setPreferredSize(new Dimension(10, 20));
		setMinimumSize(new Dimension(10, 20));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setFont(getFont());
		paint(g, text, trailing, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a heading in a box; the card uses the same drawing. The font must already be set. */
	static void paint(Graphics2D g, String text, String trailing, int x, int y, int w, int h)
	{
		int mid = y + h / 2 + 2;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(x + 4, mid - 4);
		diamond.lineTo(x + 8, mid);
		diamond.lineTo(x + 4, mid + 4);
		diamond.lineTo(x, mid);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);

		FontMetrics fm = g.getFontMetrics();
		int textX = x + 13;
		int baseline = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.GOLD);
		g.drawString(text, textX, baseline);

		int lineStart = textX + fm.stringWidth(text) + 6;
		int lineEnd = x + w;
		if (trailing != null && !trailing.isEmpty())
		{
			int tw = fm.stringWidth(trailing);
			lineEnd = x + w - tw - 6;
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(trailing, x + w - tw, baseline);
		}
		if (lineEnd > lineStart)
		{
			g.setPaint(new GradientPaint(lineStart, 0, Theme.alpha(Theme.GOLD, 110), lineEnd, 0, Theme.alpha(Theme.GOLD, 0)));
			g.drawLine(lineStart, mid, lineEnd, mid);
		}
	}
}

package com.codex.quartermaster.ui;

import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.function.IntConsumer;
import javax.swing.JComponent;

/**
 * Tabs drawn as one engraved strip: the chosen segment is lit from below by a
 * gold glow, the rest sit quietly in the ink.
 */
public class Segmented extends JComponent
{
	private final String[] labels;
	private final boolean large;
	private final Animator slide = new Animator(this);
	private int selected;
	private int hover = -1;
	private IntConsumer listener;

	public Segmented(boolean large, String... labels)
	{
		this.labels = labels;
		this.large = large;
		setFont(large ? Theme.title() : Theme.small());
		int h = large ? 28 : 22;
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				setSelected(indexAt(e.getX()), true);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	public void onChange(IntConsumer listener)
	{
		this.listener = listener;
	}

	public int getSelected()
	{
		return selected;
	}

	public void setSelected(int index, boolean notify)
	{
		if (index < 0 || index >= labels.length)
		{
			return;
		}
		boolean changed = index != selected;
		selected = index;
		slide.set(index, true);
		repaint();
		if (changed && notify && listener != null)
		{
			listener.accept(index);
		}
	}

	private int indexAt(int x)
	{
		int w = Math.max(1, getWidth());
		return Math.max(0, Math.min(labels.length - 1, x * labels.length / w));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float seg = w / (float) labels.length;

		RoundRectangle2D strip = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setColor(Theme.INK_DEEP);
		g.fill(strip);

		float x = (float) (slide.get() * seg);
		RoundRectangle2D lit = new RoundRectangle2D.Float(x + 2, 2, seg - 4, h - 4, 6, 6);
		g.setPaint(new GradientPaint(0, 2, Theme.CARD_TOP, 0, h, Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35)));
		g.fill(lit);
		g.setColor(Theme.alpha(Theme.GOLD, 120));
		g.draw(lit);
		g.setColor(Theme.GOLD_BRIGHT);
		g.fillRect(Math.round(x + seg * 0.3f), h - 4, Math.round(seg * 0.4f), 1);

		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < labels.length; i++)
		{
			int tx = Math.round(i * seg + (seg - fm.stringWidth(labels[i])) / 2);
			int ty = (h + fm.getAscent()) / 2 - (large ? 2 : 1);
			java.awt.Color color = i == selected ? Theme.GOLD_BRIGHT : i == hover ? Theme.TEXT : Theme.TEXT_MUTED;
			Ui.shadowed(g, labels[i], tx, ty, color);
		}
		g.setColor(Theme.STROKE_SOFT);
		g.draw(strip);
		g.dispose();
	}
}

package com.codex.quartermaster.ui;

import java.awt.BasicStroke;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;

/** The Quartermaster's mark: a gilt-banded supply crate with a teal potion flask standing before it. */
public final class Sigil
{
	private Sigil()
	{
	}

	public static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		paint(g, 0, 0, size);
		g.dispose();
		return image;
	}

	/** Draws the mark in a size by size box. */
	public static void paint(Graphics2D g, float x, float y, float size)
	{
		float s = size / 16f;
		float stroke = Math.max(0.6f, 0.55f * s);

		// The crate, lit from the top left, with two planks and a gilt band across it.
		RoundRectangle2D crate = new RoundRectangle2D.Float(x + 0.8f * s, y + 3.2f * s, 11.2f * s, 10.6f * s, 2.2f * s, 2.2f * s);
		g.setPaint(new GradientPaint(x, y + 3 * s, Theme.mix(Theme.GOLD_DIM, Theme.GOLD, 0.35f), x + 12 * s, y + 14 * s, Theme.mix(Theme.GOLD_DIM, Theme.INK_DEEP, 0.45f)));
		g.fill(crate);
		g.setStroke(new BasicStroke(stroke));
		g.setColor(Theme.INK_DEEP);
		g.draw(crate);
		g.setColor(Theme.alpha(Theme.INK_DEEP, 150));
		g.drawLine(Math.round(x + 1.2f * s), Math.round(y + 6.8f * s), Math.round(x + 11.6f * s), Math.round(y + 6.8f * s));
		g.drawLine(Math.round(x + 1.2f * s), Math.round(y + 10.4f * s), Math.round(x + 11.6f * s), Math.round(y + 10.4f * s));
		g.setPaint(new GradientPaint(x, y + 3 * s, Theme.GOLD_BRIGHT, x, y + 14 * s, Theme.GOLD));
		g.fill(new RoundRectangle2D.Float(x + 5.2f * s, y + 3.2f * s, 2.4f * s, 10.6f * s, 0.8f * s, 0.8f * s));
		g.setColor(Theme.INK_DEEP);
		g.draw(new RoundRectangle2D.Float(x + 5.2f * s, y + 3.2f * s, 2.4f * s, 10.6f * s, 0.8f * s, 0.8f * s));

		// The flask: a round body, a short neck and a cork, filled with teal.
		float fx = x + 11.6f * s;
		float fy = y + 11.4f * s;
		float r = 3.6f * s;
		Path2D flask = new Path2D.Float();
		flask.append(new Ellipse2D.Float(fx - r, fy - r, r * 2, r * 2), false);
		flask.append(new RoundRectangle2D.Float(fx - 1.2f * s, fy - r - 2.6f * s, 2.4f * s, 3.2f * s, 0.6f * s, 0.6f * s), false);
		g.setColor(Theme.INK_DEEP);
		g.setStroke(new BasicStroke(Math.max(1.6f, 1.8f * s)));
		g.draw(flask);
		g.setColor(Theme.alpha(Theme.TEXT, 70));
		g.fill(flask);
		g.setPaint(new GradientPaint(fx, fy - r, Theme.mix(Theme.TEAL, Theme.TEXT, 0.35f), fx, fy + r, Theme.mix(Theme.TEAL, Theme.INK_DEEP, 0.3f)));
		g.fill(new Ellipse2D.Float(fx - r + 0.6f * s, fy - r * 0.35f, (r - 0.6f * s) * 2, r * 1.3f));
		g.setColor(Theme.GOLD_DIM);
		g.fill(new RoundRectangle2D.Float(fx - 1.1f * s, fy - r - 3.2f * s, 2.2f * s, 1.4f * s, 0.6f * s, 0.6f * s));
		g.setColor(Theme.alpha(java.awt.Color.WHITE, 150));
		g.fill(new Ellipse2D.Float(fx - r * 0.55f, fy - r * 0.6f, r * 0.45f, r * 0.45f));
	}
}

package com.codex.quartermaster.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * A vertical stack where every child spans the full width at its preferred height.
 * It tracks the viewport width so nothing ever scrolls sideways in the side panel.
 */
public class StackPanel extends JPanel implements Scrollable
{
	public StackPanel(int gap, int pad)
	{
		super(new StackLayout(gap));
		setOpaque(false);
		setBorder(new EmptyBorder(pad, pad, pad, pad));
	}

	public StackPanel space(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new Dimension(1, height));
		add(spacer);
		return this;
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return Math.max(16, visibleRect.height - 32);
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	static final class StackLayout implements LayoutManager
	{
		private final int gap;

		StackLayout(int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				width = Math.max(width, d.width);
				height += d.height;
				visible++;
			}
			height += Math.max(0, visible - 1) * gap;
			return new Dimension(width + in.left + in.right, height + in.top + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets in = parent.getInsets();
			int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}
}

package com.codex.quartermaster.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tablet: a big number, its label, and a quiet line of context. */
class StatTile extends JComponent
{
	private final String value;
	private final String label;
	private final String note;
	private final Color color;

	StatTile(String value, String label, String note, Color color)
	{
		this.value = value;
		this.label = label;
		this.note = note;
		this.color = color;
		setPreferredSize(new Dimension(10, 54));
		setOpaque(false);
		setToolTipText(note == null || note.isEmpty() ? label : label + ": " + note);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, value, label, note, color, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a tablet in a box; the card uses the same drawing. */
	static void paint(Graphics2D g, String value, String label, String note, Color color, int x, int y, int w, int h)
	{
		RoundRectangle2D shape = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(x, y, Theme.CARD_TOP, x, y + h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);
		g.setColor(Theme.alpha(color, 160));
		g.fillRect(x + Theme.RADIUS, y + 1, w - Theme.RADIUS * 2, 1);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label.toUpperCase(), x + 8, y + 6 + small.getAscent());

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(value, bold, w - 16), x + 8, y + 8 + small.getHeight() + bold.getAscent(), color);
		if (note != null && !note.isEmpty())
		{
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip(note, small, w - 16), x + 8, y + h - 6);
		}
	}
}

package com.codex.quartermaster.ui;

import com.codex.quartermaster.core.Plan;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import java.util.Map;
import javax.swing.JComponent;

/**
 * One supply against the bank: the item in its slot, what is held and what a trip takes, how many
 * trips that lasts on the right, and a row of ration pips, one a trip up to the restock target, so
 * the supply that runs out first stands out at a glance.
 */
class SupplyRow extends JComponent
{
	private static final int MAX_PIPS = 25;

	private final Plan.Line line;
	private final String name;
	private final int target;
	private final int warn;
	private final boolean first;
	private final ItemIcons icons;

	SupplyRow(Plan.Line line, View view, int target, boolean first, ItemIcons icons)
	{
		this.line = line;
		this.name = view.name(line);
		this.target = target;
		this.warn = view.warn;
		this.first = first;
		this.icons = icons;
		setOpaque(false);
		setPreferredSize(new Dimension(10, Well.SIZE + 12));
		StringBuilder tip = new StringBuilder("<html><b>").append(Ui.escape(name)).append("</b>");
		for (Map.Entry<Integer, Long> e : line.getHeld().entrySet())
		{
			tip.append("<br>").append(Ui.escape(view.name(e.getKey()))).append(": ").append(String.format("%,d", e.getValue()));
		}
		if (line.getHeld().isEmpty())
		{
			tip.append("<br>None held");
		}
		if (!line.isKept())
		{
			tip.append("<br>").append(line.isMeasured() ? "Measured from your trips" : "Planned for this kit");
		}
		setToolTipText(tip.append("</html>").toString());
	}

	private int icon()
	{
		// Show the item the player has most of, so the row looks like their own bank.
		return line.getHeld().isEmpty() ? line.getSupply().getIcon() : line.getHeld().keySet().iterator().next();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		boolean kept = line.isKept();
		Color color = kept ? Theme.TEXT_MUTED : Theme.trips(line.getTrips(), warn);
		Well.paint(g, 0, 4, icons == null ? null : icons.icon(icon(), this::repaint), first ? Theme.alpha(color, 200) : null);

		int tx = Well.SIZE + 12;
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		String trips = kept ? "kept" : Format.trips(line.getTrips());
		g.setFont(kept ? Theme.small() : Theme.title());
		FontMetrics tf = g.getFontMetrics();
		int tw = tf.stringWidth(trips);
		int base = 4 + bold.getAscent();
		Ui.shadowed(g, trips, w - tw, base, color);

		g.setFont(Theme.body());
		FontMetrics fm = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(name, fm, w - tx - tw - 8), tx, base, first ? Theme.TEXT : Theme.mix(Theme.TEXT, Theme.TEXT_MUTED, 0.25));

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		String note = kept
			? "comes back every trip"
			: Format.amount(line.getHave()) + View.unit(line) + "  -  " + Format.perTrip(line.getPerTrip()) + " a trip" + (line.isMeasured() ? "*" : "");
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(Ui.clip(note, small, w - tx), tx, base + 13);

		if (!kept)
		{
			paintPips(g, tx, Well.SIZE + 5, w - tx, color);
		}
		g.dispose();
	}

	private void paintPips(Graphics2D g, int x, int y, int width, Color color)
	{
		int have = Math.min(line.getTrips(), target);
		if (target > MAX_PIPS)
		{
			RoundRectangle2D track = new RoundRectangle2D.Float(x, y, width, 4, 4, 4);
			g.setColor(Theme.INK_DEEP);
			g.fill(track);
			float fill = width * have / (float) target;
			if (fill > 0)
			{
				g.setPaint(new GradientPaint(x, 0, Theme.mix(color, Theme.INK, 0.4), x + width, 0, color));
				g.fill(new RoundRectangle2D.Float(x, y, Math.max(3, fill), 4, 4, 4));
			}
			return;
		}
		float gap = 2;
		float pip = (width - gap * (target - 1)) / target;
		for (int i = 0; i < target; i++)
		{
			float px = x + i * (pip + gap);
			RoundRectangle2D r = new RoundRectangle2D.Float(px, y, pip, 4, 2, 2);
			if (i < have)
			{
				g.setPaint(new GradientPaint(0, y, Theme.mix(color, Color.WHITE, 0.2), 0, y + 4, color));
			}
			else
			{
				g.setColor(Theme.INK_DEEP);
			}
			g.fill(r);
		}
	}
}

package com.codex.quartermaster.ui;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;

/**
 * The Codex look: warm ink, aged gold and a single arcane teal, drawn with the
 * game's own fonts so the panel reads as part of Gielinor rather than a web page.
 * The Quartermaster keeps gold for what is well stocked, turns ember as a supply runs low and
 * blood when it is out, so a row's colour says how long it will last before it is read.
 */
public final class Theme
{
	public static final Color INK = new Color(23, 20, 16);
	public static final Color INK_DEEP = new Color(16, 14, 11);
	public static final Color CARD = new Color(34, 30, 24);
	public static final Color CARD_TOP = new Color(42, 37, 29);
	public static final Color CARD_HOVER = new Color(48, 42, 33);
	public static final Color STROKE = new Color(66, 56, 42);
	public static final Color STROKE_SOFT = new Color(48, 41, 32);

	public static final Color GOLD = new Color(214, 178, 106);
	public static final Color GOLD_BRIGHT = new Color(246, 214, 144);
	public static final Color GOLD_DIM = new Color(132, 108, 66);
	public static final Color TEAL = new Color(96, 184, 170);
	public static final Color GREEN = new Color(130, 196, 108);
	public static final Color EMBER = new Color(222, 134, 86);
	public static final Color BLOCKED = new Color(176, 92, 84);
	public static final Color BLOOD = new Color(204, 70, 60);
	public static final Color BLOOD_DEEP = new Color(120, 32, 28);
	public static final Color VIOLET = new Color(176, 132, 222);

	public static final Color TEXT = new Color(234, 224, 202);
	public static final Color TEXT_MUTED = new Color(160, 148, 126);
	public static final Color TEXT_FAINT = new Color(110, 100, 84);

	public static final int RADIUS = 10;
	public static final int GUTTER = 8;

	private Theme()
	{
	}

	public static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	public static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	public static Color mix(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			(int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	/** Progress colour: ember when just begun, gold through the middle, green when nearly there. */
	public static Color progressColor(double progress)
	{
		if (progress >= 1)
		{
			return GREEN;
		}
		if (progress < 0.5)
		{
			return mix(EMBER, GOLD, progress * 2);
		}
		return mix(GOLD, TEAL, (progress - 0.5) * 2);
	}

	/** Item quantities in the game's own colours: yellow, white from 100K, green from 10M. */
	public static final Color QTY_YELLOW = new Color(255, 255, 0);
	public static final Color QTY_WHITE = new Color(255, 255, 255);
	public static final Color QTY_GREEN = new Color(0, 255, 128);

	/**
	 * How long a supply lasts, as a colour: blood when it is out or will not last the trip,
	 * ember when only a few trips are left, gold when it is comfortable and green when plentiful.
	 */
	public static Color trips(int trips, int warn)
	{
		if (trips <= 0)
		{
			return BLOOD;
		}
		if (trips <= warn)
		{
			return EMBER;
		}
		if (trips >= warn * 8)
		{
			return GREEN;
		}
		return GOLD;
	}

	/** Smooth shapes, but the pixel fonts stay crisp. */
	public static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}
}

